# Code snippet to demonstrate the risk of using eval() with untrusted input
def unsafe_evaluate(expr):
    return eval(expr)

# Example of a malicious expression that could cause harm
malicious_expr = "open('/etc/passwd', 'r').read()"
try:
    print(unsafe_evaluate(malicious_expr))
except Exception as e:
    print(f"Error: {e}")
